'use strict';
(()=>{
 const script=document.currentScript||[...document.scripts].find(s=>s.src.endsWith('/navigation.js'));
 const root=new URL('.',script?.src||location.href);
 const link=path=>new URL(path,root).href;
 const path=location.pathname.split('/').filter(Boolean).pop()||'index.html';
 const shortNames={'Introduction':'Intro','Guided lab':'Lab','Examples':'Examples','Audit tutorial':'Audit'};
 const items=[['index.html','Introduction'],['lab.html','Guided lab'],['examples.html','Examples'],['tutorial.html','Audit tutorial']];
 const header=document.createElement('header');header.className='guide-header';header.innerHTML=`<div class="guide-header-inner"><a class="guide-wordmark" href="${link('index.html')}" aria-label="Duo Field Guide home"><span class="guide-fold-mark" aria-hidden="true"><i></i><i></i></span><strong>duo</strong><span>A DEVELOPER FIELD GUIDE</span></a><nav class="guide-primary-nav" aria-label="Guide navigation">${items.map(([href,title])=>`<a aria-label="${title}" href="${link(href)}" ${path===href?'aria-current="page"':''}><span class="nav-desktop">${title}</span><span class="nav-mobile">${shortNames[title]}</span></a>`).join('')}</nav><button class="guide-find" type="button" id="open-guide-search" aria-label="Find a chapter or reference">Find anything <kbd>⌘ K</kbd></button></div>`;
 const placeholder=document.getElementById('guide-header');const previous=document.querySelector('body > .site-header');
 if(placeholder)placeholder.replaceWith(header);else if(previous)previous.replaceWith(header);else document.body.prepend(header);
 document.body.classList.add('guide-has-nav');
 const references=[['Meet iPhone Duo','Start here · displays and poses','index.html#meet'],['Adaptive layouts','Available space · fixed widths · safe areas','index.html#resize'],['The fold and reserved regions','Division · occlusion · cameras','index.html#regions'],['System controls and overflow','Side bars · toolbars · actions','index.html#bars'],['State continuity','Drafts · selection · scenePhase','index.html#state'],['Build your first screen','Knowledge check · SDK · next steps','index.html#build'],['Native SwiftUI starter','Download · Xcode project · notes app','index.html#build'],['Interactive developer lab','Experiments · fragile / adaptive · inspector','lab.html'],['Mail, Notes, Media, and Layout','Interactive example apps','examples.html'],['Your first iPhone Duo audit','Hands-on SwiftUI tutorial','tutorial.html'],['API reference','SwiftUI · UIKit · arrangements · signatures','references/apple-hig-designing-for-iphone-duo.html'],['Cameras and scene accessories','Camera direction · outer display','references/cameras-and-scene-accessories.html'],['System behaviors','Multiple windows · accessibility · widgets','references/system-behaviors.html'],['Shipping your app','App Store assets · screenshots · previews','references/shipping.html'],['Sources and methodology','Apple sources · model limitations · review dates','sources.html']];
 const dialog=document.createElement('dialog');dialog.className='guide-search';dialog.setAttribute('aria-labelledby','guide-search-label');dialog.innerHTML='<div class="guide-search-top"><label id="guide-search-label" for="guide-search-input">Find in the guide</label><input type="search" id="guide-search-input" autocomplete="off" placeholder="Fold, bars, Swift…"><button type="button" id="close-guide-search" aria-label="Close search">×</button></div><div class="guide-search-results" id="guide-search-results"></div><p class="guide-search-foot">Chapters, examples, and reference topics · Esc to close</p>';document.body.append(dialog);
 const input=document.getElementById('guide-search-input'),results=document.getElementById('guide-search-results');
 function render(){const q=input.value.trim().toLowerCase();const filtered=references.filter(row=>row.join(' ').toLowerCase().includes(q));results.replaceChildren(...filtered.map(([title,description,href])=>{const a=document.createElement('a');a.href=link(href);const span=document.createElement('span'),strong=document.createElement('strong'),small=document.createElement('small');strong.textContent=title;small.textContent=description;span.append(strong,small);a.append(span,document.createTextNode('↗'));a.addEventListener('click',e=>{dialog.close();if(href.startsWith('index.html#')&&(path==='index.html'||location.pathname.endsWith('/'))){e.preventDefault();location.hash=href.split('#')[1];}});return a;}));if(!filtered.length){const p=document.createElement('p');p.textContent='No matching topics. Try “layout”, “camera”, or “SwiftUI”.';results.append(p);}}
 function open(){input.value='';render();dialog.showModal();input.focus();}
 document.getElementById('open-guide-search').addEventListener('click',open);document.getElementById('close-guide-search').addEventListener('click',()=>dialog.close());input.addEventListener('input',render);dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();if(dialog.open)dialog.close();else open();}});
})();
